-- One-time repair of training times already shifted by the DST bug, plus a
-- reusable function to do it.
--
-- Background: before 20261025120000_fix_dst_recurrence, recurring occurrences were
-- generated by adding absolute intervals, so occurrences generated across a DST
-- switch landed an hour off (e.g. 18:00 instead of 19:00). The generator fix stops
-- NEW drift, but occurrences already written at the wrong time stay wrong — and
-- since the generator templates off the latest occurrence, the wrong time would be
-- carried forward. This repairs them.
--
-- Strategy (chosen: anchor to the most recent session): for each recurring series,
-- take the local (Europe/Berlin) time-of-day of its anchor occurrence — the most
-- recent occurrence at or before now(), else the earliest — and snap every FUTURE
-- occurrence of that series to that local time-of-day, keeping each occurrence's
-- local calendar date. endDateTime / answerDeadline / meetingDateTime move by the
-- same delta, so durations and offsets are preserved. Past occurrences (history)
-- are never touched, and rows already at the right time are left alone.

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.repair_recurrence_local_time(p_tz text DEFAULT 'Europe/Berlin')
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_count integer;
BEGIN
  WITH anchor AS (
    -- Per series: the local time-of-day of the most recent past occurrence,
    -- falling back to the earliest occurrence if the series has no past session.
    SELECT DISTINCT ON (e."key")
           e."key" AS key,
           (e."startingDateTime" AT TIME ZONE p_tz)::time AS tod
    FROM public.events e
    WHERE e.recurrence <> 'None'::public."EventRecurrence"
    ORDER BY e."key",
             (e."startingDateTime" <= now()) DESC,
             CASE WHEN e."startingDateTime" <= now() THEN e."startingDateTime" END DESC NULLS LAST,
             e."startingDateTime" ASC
  ),
  target AS (
    SELECT e.id,
           e."startingDateTime" AS old_start,
           -- same local calendar date, anchor's local time-of-day
           (((e."startingDateTime" AT TIME ZONE p_tz)::date + a.tod) AT TIME ZONE p_tz) AS new_start
    FROM public.events e
    JOIN anchor a ON a.key = e."key"
    WHERE e.recurrence <> 'None'::public."EventRecurrence"
      AND e."startingDateTime" > now()
  ),
  upd AS (
    UPDATE public.events e
    SET "startingDateTime" = t.new_start,
        "endDateTime"      = e."endDateTime"    + (t.new_start - t.old_start),
        "answerDeadline"   = CASE WHEN e."answerDeadline"  IS NULL THEN NULL
                                  ELSE e."answerDeadline"  + (t.new_start - t.old_start) END,
        "meetingDateTime"  = CASE WHEN e."meetingDateTime" IS NULL THEN NULL
                                  ELSE e."meetingDateTime" + (t.new_start - t.old_start) END
    FROM target t
    WHERE e.id = t.id
      AND t.new_start <> t.old_start   -- idempotent: skip rows already correct
    RETURNING 1
  )
  SELECT count(*)::int INTO v_count FROM upd;

  RETURN v_count;
END;
$function$
;

-- Maintenance utility: not for general clients.
REVOKE ALL ON FUNCTION public.repair_recurrence_local_time(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.repair_recurrence_local_time(text) TO service_role;

-- Apply the one-time repair for the switch that just happened.
SELECT public.repair_recurrence_local_time('Europe/Berlin');
